257	    @Override
258	    @Transactional
259	    public void saveOwner(Owner owner) throws DataAccessException {
260	        boolean isNew = owner.isNew();
261	        // Resolve the effective registration date (supplied, or defaulted to the server date) and
262	        // roll it forward to the next business day so it never lands on a weekend. Everything
263	        // derived from the registration date below must use this adjusted value.
264	        LocalDate registrationDate = toBusinessDay(
265	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now());
266	        owner.setRegistrationDate(registrationDate);
267	        if (owner.isNew()) {
268	            // The householdId is deterministic: the first 12 hex characters of SHA-256 over
269	            // (normalizedLastName | postcode), so owners with the same last name and postcode share
270	            // it automatically. It no longer feeds the identityKey, but is still reported and drives
271	            // the household member count and level cap below.
272	            owner.setHouseholdId(computeHouseholdId(owner));
273	            // The household is keyed on (last name, postcode), so the members are the existing owners
274	            // sharing both with this owner.
275	            List<Owner> householdMembers = findHouseholdMembers(owner);
276	            // Size of the household after this create: the existing members plus this new owner.
277	            owner.setHouseholdMemberCount(householdMembers.size() + 1);
278	            // A new owner joining an existing household has its derived membershipLevel capped at one
279	            // above the current maximum membershipLevel among its household members, so a new member
280	            // can never leap more than one level past the household. With no existing member no cap
281	            // applies.
282	            if (!householdMembers.isEmpty()) {
283	                int maxLevel = householdMembers.stream()
284	                    .mapToInt(Owner::getMembershipLevel)
285	                    .max()
286	                    .getAsInt();
287	                owner.setMembershipLevelCap(maxLevel + 1);
288	            }
289	        }
290	        // Single duplicate check: reject only when the new owner's WHOLE identityKey (the SHA-256 of
291	        // normalizedTelephone | email-or-empty | soundex(lastName)) equals an existing owner's. This
292	        // is the only 409; there is no separate household-duplicate rejection.
293	        if (owner.isNew() && isIdentityKeyAlreadyUsed(owner)) {
294	            throw new DuplicateIdentityException(owner.getIdentityKey());
295	        }
296	        // Soft-match: not a hard identityKey duplicate, but shares an existing owner's
297	        // soundex(lastName) and postcode. Still created, but flagged as a possible duplicate pointing
298	        // at the matching owner. Because the telephone is part of the identityKey, two owners with the
299	        // same last name and postcode but different telephones are flagged here rather than rejected.
300	        if (owner.isNew()) {
301	            Owner softMatch = findPossibleDuplicate(owner);
302	            if (softMatch != null) {
303	                owner.setPossibleDuplicate(true);
304	                owner.setPossibleDuplicateOf(softMatch.getId());
305	            }
306	        }
307	        if (owner.isNew()
308	            && countOwnersInCity(owner) >= CityOwnerLimitExceededException.MAX_OWNERS_PER_CITY) {
309	            throw new CityOwnerLimitExceededException(owner.getCity());
310	        }
311	        if (owner.isNew()
312	            && countOwnersRegisteredOn(registrationDate) >= DailyOwnerLimitExceededException.MAX_OWNERS_PER_DAY) {
313	            throw new DailyOwnerLimitExceededException(registrationDate);
314	        }
315	        if (owner.isNew() && owner.getCustomerCode() == null) {
316	            owner.setCustomerCode(generateCustomerCode(owner));
317	        }
318	        if (owner.isNew()) {
319	            owner.setNamesakeCount(countNamesakes(owner));
320	            owner.setBulkSignupWarning(
321	                countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
322	        }
323	        if (owner.getMembershipNumber() == null) {
324	            owner.setMembershipNumber(generateMembershipNumber(owner));
325	        }
326	        ownerRepository.save(owner);
327	        if (isNew) {
328	            AUDIT.info("owner created id={} customerCode={} membershipLevel={} membershipNumber={} registrationDate={}",
329	                owner.getId(), owner.getCustomerCode(), owner.getMembershipLevel(),
330	                owner.getMembershipNumber(), owner.getRegistrationDate());
331	        }
332	    }
333	
334	    /**
335	     * Report whether {@code owner}'s derived {@code identityKey} is already used by any existing
336	     * (non-deleted) owner. The key is the SHA-256 of telephone, email and {@code soundex(lastName)}
337	     * combined, so two owners collide only when their whole key is equal (see
338	     * {@link Owner#getIdentityKey()}).
339	     */
340	    private boolean isIdentityKeyAlreadyUsed(Owner owner) {
341	        String identityKey = owner.getIdentityKey();
342	        return ownerRepository.findAll().stream()
343	            .filter(existing -> !existing.isDeleted())
344	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
345	    }
346	
347	    /**
348	     * Find an existing owner this (new) owner soft-matches against: one sharing the same
349	     * {@code soundex(lastName)} and postcode, but carrying a different {@code identityKey}. Returns
350	     * the lowest-id such owner, or {@code null} when the owner has no last name or postcode to match
351	     * on, or nothing matches. The caller only invokes this once the hard {@code identityKey}
352	     * duplicate check has already passed.
353	     */
354	    private Owner findPossibleDuplicate(Owner owner) {
355	        String key = soundexPostcodeKey(owner);
356	        if (key == null) {
357	            return null;
358	        }
359	        String identityKey = owner.getIdentityKey();
360	        return ownerRepository.findAll().stream()
361	            .filter(existing -> !existing.isDeleted())
362	            .filter(existing -> key.equals(soundexPostcodeKey(existing))
363	                && !identityKey.equals(existing.getIdentityKey()))
364	            .min(Comparator.comparing(Owner::getId))
365	            .orElse(null);
366	    }
367	
368	    /**
369	     * Build the soft-match key, {@code soundex(lastName) + '|' + postcode}: the basis on which a new
370	     * owner is flagged a possible duplicate of an existing owner. Returns {@code null} when the owner
371	     * has no last name to encode or no postcode to key on.
372	     */
373	    private String soundexPostcodeKey(Owner owner) {
374	        String soundex = Soundex.encode(owner.getLastName());
375	        String postcode = owner.getPostcode();
376	        if (soundex.isEmpty() || postcode == null || postcode.isBlank()) {
377	            return null;
378	        }
379	        return soundex + "|" + postcode;
380	    }
381	
382	    /**
383	     * Count the owners that already exist (before this create) sharing the same first name and last
384	     * name as {@code owner}, compared case-insensitively. Returns zero when the owner's name is
385	     * unique among the existing owners.
386	     */
387	    private int countNamesakes(Owner owner) {
388	        String firstName = owner.getFirstName();
389	        String lastName = owner.getLastName();
390	        if (firstName == null || lastName == null) {
391	            return 0;
392	        }
393	        return (int) ownerRepository.findAll().stream()
394	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
395	                && lastName.equalsIgnoreCase(existing.getLastName()))
396	            .count();
397	    }
398	
399	    /**
400	     * Find the owners that already belong to the same household as {@code owner}, i.e. share both its
401	     * last name and its postcode. Last names are compared case-insensitively with collapsed
402	     * whitespace; postcodes are compared exactly. This is the same keying used by
403	     * {@link #computeHouseholdId(Owner)}, so these are exactly the existing owners that carry the
404	     * owner's computed {@code householdId}. Returns an empty list when the owner has no last name or
405	     * postcode to match on.
406	     */
407	    private List<Owner> findHouseholdMembers(Owner owner) {
408	        String key = householdKey(owner);
409	        if (key == null) {
410	            return List.of();
411	        }
412	        return ownerRepository.findAll().stream()
413	            .filter(existing -> !existing.isDeleted())
414	            .filter(existing -> key.equals(householdKey(existing)))
415	            .toList();
416	    }
417	
418	    /**
419	     * Compute an owner's deterministic {@code householdId}: the first 12 lower-case hex characters of
420	     * SHA-256 over the UTF-8 bytes of {@code normalizedLastName + '|' + postcode} (see
421	     * {@link #householdKey(Owner)}). Owners with the same last name and postcode therefore share the
422	     * same {@code householdId} automatically. Returns {@code null} when the owner has no last name or
423	     * postcode, so it does not belong to a shared household.
424	     */
425	    private String computeHouseholdId(Owner owner) {
426	        String key = householdKey(owner);
427	        return key == null ? null : sha256Hex(key, 6, false);
428	    }
429	
430	    /**
431	     * Build the owner's household key, {@code normalizedLastName + '|' + postcode}, the single value
432	     * that identifies a household. The last name is normalized case-insensitively with collapsed
433	     * whitespace (see {@link #normalizeHouseholdKey}) and the postcode is used exactly as stored.
434	     * Returns {@code null} when the owner has no last name or postcode to key on. This is the shared
435	     * basis for both {@link #computeHouseholdId(Owner)} and household membership matching, so the two
436	     * cannot drift apart.
437	     */
438	    private String householdKey(Owner owner) {
439	        String lastName = normalizeHouseholdKey(owner.getLastName());
440	        String postcode = owner.getPostcode();
441	        if (lastName == null || postcode == null || postcode.isBlank()) {
442	            return null;
443	        }
444	        return lastName + "|" + postcode;
445	    }
446	
447	    /**
448	     * Normalize a value for case-insensitive, whitespace-insensitive household comparison by
449	     * trimming, collapsing internal runs of whitespace to a single space and lower-casing it.
450	     */
451	    private String normalizeHouseholdKey(String value) {
452	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase();
453	    }
454	
455	    /**
456	     * Build an owner's {@code customerCode} as {@code '<REGION>-<HASH8>'}: REGION is the region
457	     * code resolved from the owner's postcode (falling back to the owner's city, else
458	     * {@code 'UNKNOWN'}), and HASH8 the first 8 upper-case hex characters of SHA-256 computed over
459	     * the owner's normalized telephone concatenated with the owner's last name (e.g.
460	     * {@code 'NSW-1A2B3C4D'}). There are no per-city sequence numbers; the identity is fully
461	     * derived from the owner's own attributes.
462	     * <p>
463	     * When the derived code collides with an existing owner's {@code customerCode}, a
464	     * {@code '-<n>'} suffix is appended with the smallest {@code n} of 2 or more that makes it
465	     * unique, so distinct owners always receive distinct customer codes.
466	     */
467	    private String generateCustomerCode(Owner owner) {
468	        String base = PostcodeRules.resolveRegion(owner.getPostcode(), owner.getCity()) + "-" + customerHash(owner);
469	        return deduplicateCustomerCode(base);
470	    }
471	
472	    /**
473	     * Return {@code base} when no existing owner already uses it as their {@code customerCode};
474	     * otherwise append {@code '-<n>'} with the smallest {@code n} of 2 or more that is not already
475	     * taken (counting both the bare {@code base} and any earlier {@code '-<n>'} de-duplications).
476	     */
477	    private String deduplicateCustomerCode(String base) {
478	        Set<String> existing = ownerRepository.findAll().stream()
479	            .map(Owner::getCustomerCode)
480	            .filter(Objects::nonNull)
481	            .collect(Collectors.toSet());
482	        if (!existing.contains(base)) {
483	            return base;
484	        }
485	        int n = 2;
486	        while (existing.contains(base + "-" + n)) {
487	            n++;
488	        }
489	        return base + "-" + n;
490	    }
491	
492	    /**
493	     * Compute the hash segment of an owner's {@code customerCode}: the first 8 upper-case hex
494	     * characters of SHA-256 over the UTF-8 bytes of the owner's normalized telephone concatenated
495	     * with the owner's last name.
496	     */
497	    private String customerHash(Owner owner) {
498	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
499	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
500	        return sha256Hex(telephone + lastName, 4, true);
501	    }
502	
503	    /**
504	     * Compute the leading hex of SHA-256 over the UTF-8 bytes of {@code input}: the first
505	     * {@code bytes} bytes of the digest rendered as {@code 2 * bytes} hex characters, upper-case when
506	     * {@code upperCase} is {@code true}, otherwise lower-case. Shared by the derived identifiers that
507	     * are built from a SHA-256 prefix (e.g. the household id and the customer-code hash), so the
508	     * digest handling and the "SHA-256 not available" error live in one place.
509	     */
510	    private String sha256Hex(String input, int bytes, boolean upperCase) {
511	        byte[] digest;
512	        try {
513	            digest = MessageDigest.getInstance("SHA-256")
514	                .digest(input.getBytes(StandardCharsets.UTF_8));
515	        } catch (NoSuchAlgorithmException e) {
516	            throw new IllegalStateException("SHA-256 is required but not available", e);
517	        }
518	        String format = upperCase ? "%02X" : "%02x";
519	        StringBuilder hex = new StringBuilder(bytes * 2);
520	        for (int i = 0; i < bytes; i++) {
521	            hex.append(String.format(format, digest[i]));
522	        }
523	        return hex.toString();
524	    }
525	
526	    /**
527	     * Count the owners that already exist (before this create) in the same city as {@code owner},
528	     * compared case-insensitively.
529	     */
530	    private long countOwnersInCity(Owner owner) {
531	        String city = owner.getCity();
532	        return ownerRepository.findAll().stream()
533	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
534	            .count();
535	    }
536	
537	    /**
538	     * Count the owners that already exist (before this create) whose {@code registrationDate} falls
539	     * on the given {@code date}. Used to enforce the per-day create cap.
540	     */
541	    private long countOwnersRegisteredOn(LocalDate date) {
542	        return ownerRepository.findAll().stream()
543	            .filter(existing -> date.equals(existing.getRegistrationDate()))
544	            .count();
545	    }
546	
547	    /**
548	     * Fixed public holidays that registration dates must never fall on. Together with weekends these
549	     * are the non-business days skipped by {@link #toBusinessDay(LocalDate)}.
550	     */
551	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
552	        LocalDate.parse("2026-01-01"),
553	        LocalDate.parse("2026-01-26"),
554	        LocalDate.parse("2026-04-25"),
555	        LocalDate.parse("2026-12-25"),
556	        LocalDate.parse("2026-12-28"));
557	
558	    /**
559	     * Roll {@code date} forward to the next business day, skipping weekends (Saturday and Sunday) and
560	     * the fixed {@link #PUBLIC_HOLIDAYS public holidays}. A date already on a business day is returned
561	     * unchanged. Registration dates are required to fall on a business day.
562	     */
563	    private LocalDate toBusinessDay(LocalDate date) {
564	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
565	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
566	            || PUBLIC_HOLIDAYS.contains(date)) {
567	            date = date.plusDays(1);
568	        }
569	        return date;
570	    }
571	
572	    /**
573	     * Build an owner's {@code membershipNumber} as {@code '<customerCode>-M<YY>'}, where YY is the
574	     * last two digits of the fiscal year of the owner's business-day-adjusted
575	     * {@code registrationDate} (the fiscal year starting 1 July), e.g. {@code 'NSW-1A2B3C4D-M27'}.
576	     */
577	    private String generateMembershipNumber(Owner owner) {
578	        String yy = String.format("%02d", Owner.fiscalYearOf(owner.getRegistrationDate()) % 100);
579	        return String.format("%s-M%s", owner.getCustomerCode(), yy);
580	    }
