588	    /**
589	     * Find the owner originally created under the given {@code Idempotency-Key}, or {@code null} when
590	     * the key is blank or no (non-deleted) owner carries it. Used by the create endpoint to recognise
591	     * a repeated create and return the first-created owner instead of creating a duplicate.
592	     */
593	    @Override
594	    @Transactional(readOnly = true)
