371	    /**
372	     * Derive the owner's read-only {@code checkDigit}: a single Luhn check digit (0-9) computed
373	     * over the digits contained in the owner's {@code customerCode}. Non-digit characters (the
374	     * '-' separators and letters) are ignored. Returns {@code null} when no {@code customerCode}
375	     * has been assigned yet.
376	     */
377	    @Transient
378	    public Integer getCheckDigit() {
379	        if (this.customerCode == null) {
380	            return null;
381	        }
382	        int sum = 0;
383	        boolean dbl = true;
384	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
385	            char c = this.customerCode.charAt(i);
386	            if (c < '0' || c > '9') {
387	                continue;
388	            }
389	            int d = c - '0';
390	            if (dbl) {
391	                d *= 2;
392	                if (d > 9) {
393	                    d -= 9;
394	                }
395	            }
396	            sum += d;
397	            dbl = !dbl;
398	        }
399	        return (10 - (sum % 10)) % 10;
400	    }
