402	    /**
403	     * Derive the owner's {@code identityKey}, the single value used to detect duplicate owners: the
404	     * full lower-case hex SHA-256 of {@code normalizedTelephone + '|' + lowerEmail + '|' +
405	     * soundex(lastName)}. The telephone and email are already stored in their canonical (E.164 /
406	     * lower-cased) form, so a {@code null} or blank email contributes an empty middle segment, and
407	     * the last name is reduced to its {@link Soundex} code (empty when there is no last name). Two
408	     * owners are duplicates only when their whole {@code identityKey} is equal.
409	     */
410	    @Transient
411	    public String getIdentityKey() {
412	        String telephonePart = this.telephone == null ? "" : this.telephone;
413	        String emailPart = (this.email == null || this.email.isBlank()) ? "" : this.email;
414	        String soundexPart = Soundex.encode(getLastName());
415	        return sha256Hex(telephonePart + "|" + emailPart + "|" + soundexPart);
416	    }
