418	    /**
419	     * Compute the full lower-case hex SHA-256 over the UTF-8 bytes of {@code input} (64 hex
420	     * characters). Used to derive the owner's {@code identityKey}.
421	     */
422	    private static String sha256Hex(String input) {
423	        byte[] digest;
424	        try {
425	            digest = MessageDigest.getInstance("SHA-256")
426	                .digest(input.getBytes(StandardCharsets.UTF_8));
427	        }
428	        catch (NoSuchAlgorithmException e) {
429	            throw new IllegalStateException("SHA-256 is required but not available", e);
430	        }
431	        StringBuilder hex = new StringBuilder(digest.length * 2);
432	        for (byte b : digest) {
433	            hex.append(String.format("%02x", b));
434	        }
435	        return hex.toString();
436	    }
